# Searches this database's records by name or meaning.
RECORD = {
    "id": "JAH-NMB3-000001",
    "name": "Aung အောင်",
    "kind": "first-name",
    "meaning": "Aung (အောင်) is a unisex given name in Burmese. Meaning: Success. Unisex; the most auspicious root."
}
ARCHIVE = [RECORD]  # extend: load the full archive from index.jsonl.gz to search all records
def lookup(query):
    q = query.strip().lower()
    return [r for r in ARCHIVE if q in r['name'].lower() or q in r['meaning'].lower()]
if __name__ == '__main__':
    hits = lookup("Aun")
    for h in hits:
        print(h['id'], '|', h['name'], '|', h['meaning'])

